var BROKERAGE_PCT = {
	zerodha: 0,
	upstox: .0025,
	angel_one: .001
};
var BROKERAGE_CAP = 20;
var estimateCharges = (broker, side, turnover) => {
	const pct = BROKERAGE_PCT[broker] ?? .0025;
	const brokerage = +Math.min(turnover * pct, BROKERAGE_CAP).toFixed(2);
	const stt = +(turnover * .001).toFixed(2);
	const exchange = +(turnover * 297e-7).toFixed(2);
	const sebi = +(turnover * 1e-6).toFixed(2);
	const gst = +((brokerage + exchange + sebi) * .18).toFixed(2);
	const stamp = side === "buy" ? +(turnover * 15e-5).toFixed(2) : 0;
	return {
		brokerage,
		stt,
		exchange,
		gst,
		sebi,
		stamp,
		total: +(brokerage + stt + exchange + sebi + gst + stamp).toFixed(2)
	};
};
var totalChargesFor = (orders) => +orders.reduce((sum, o) => sum + estimateCharges(o.broker, o.side === "sell" ? "sell" : "buy", Number(o.total_inr)).total, 0).toFixed(2);
